class Solution {
public:
    vector<string> divideString(string s, int k, char fill) {
        vector<string> res;
        int n = s.size();
        for (int i = 0; i < n; i += k) {
            string chunk = s.substr(i, k);
            if ((int)chunk.size() < k) {
                chunk.append(k - chunk.size(), fill);
            }
            res.push_back(chunk);
        }
        return res;
    }
};

class Solution {
    public String[] divideString(String s, int k, char fill) {
        int n = s.length();
        int groups = (n + k - 1) / k;
        String[] res = new String[groups];
        int idx = 0;
        for (int i = 0; i < n; i += k) {
            int end = Math.min(n, i + k);
            StringBuilder sb = new StringBuilder(s.substring(i, end));
            while (sb.length() < k) {
                sb.append(fill);
            }
            res[idx++] = sb.toString();
        }
        return res;
    }
}

var divideString = function(s, k, fill) {
    const res = [];
    for (let i = 0; i < s.length; i += k) {
        let chunk = s.slice(i, i + k);
        if (chunk.length < k) {
            chunk += fill.repeat(k - chunk.length);
        }
        res.push(chunk);
    }
    return res;
};
